import csv
import io

COLUMNS = ["id", "customer", "total"]


def write_orders(orders):
    buffer = io.StringIO()
    writer = csv.writer(buffer)
    for order in orders:
        writer.writerow([order[column] for column in COLUMNS])
    return buffer.getvalue()

import unittest

from export import write_orders


class WriteOrdersTest(unittest.TestCase):
    def test_writes_one_row_per_order(self):
        orders = [
            {"id": 1, "customer": "Ani", "total": 150000},
            {"id": 2, "customer": "Budi", "total": 98000},
        ]
        self.assertEqual("1,Ani,150000\r\n2,Budi,98000\r\n", write_orders(orders))
